def cdc_chunks(data, avg=4<<20, min_sz=1<<20, max_sz=8<<20):
    mask = avg - 1           # boundary when low bits are zero
    start, h = 0, 0
    for i, b in enumerate(data):
        h = rolling_update(h, b, window=48)   # Rabin / Gear hash
        size = i - start + 1
        if (size >= min_sz and (h & mask) == 0) or size >= max_sz:
            yield data[start:i+1]; start = i + 1
    if start < len(data): yield data[start:]

for node in union(remote, local, synced):
    lc = local[node] != synced[node]
    rc = remote[node] != synced[node]
    if lc and not rc: plan.upload(node)
    elif rc and not lc: plan.download(node)
    elif lc and rc and local[node] != remote[node]:
        plan.conflict_copy(node)    # keep both, never silently overwrite
    # after each op succeeds: synced[node] = new agreed state

def put_block(hash, data):
    frags = rs_encode(data, k=6, m=3)            # 9 fragments
    disks = placement.pick(hash, n=9, per_zone=3, distinct_hosts=True)
    write_all(frags, disks, require_acks=9, timeout=2s)  # or >=7 then repair
    block_index.put(hash, locator(disks))
def get_block(hash):
    frags = read_any(block_index.locator(hash), need=6)  # fastest 6 of 9
    return rs_decode(frags)
